param([string]$AfterFxPath="C:\Program Files\Adobe\Adobe After Effects 2025\Support Files\AfterFX.exe",[int]$ProofTimeoutSeconds=35)
$ErrorActionPreference="Stop";$root=(Resolve-Path (Join-Path $PSScriptRoot "..\..")).Path;$config=Join-Path $env:LOCALAPPDATA "EditFlow2\bridge-config.json";$runId=(Get-Date -Format "yyyyMMdd-HHmmssfff")+"-"+[Guid]::NewGuid().ToString("N").Substring(0,8);$dir=Join-Path $root ("proofs\artifacts\m4-point-tracking-p1-p3\run-"+$runId);$result=Join-Path $dir "result.json";$ready=Join-Path $dir "broker-ready.json";$stdout=Join-Path $dir "node.stdout.log";$stderr=Join-Path $dir "node.stderr.log";$cleanup=Join-Path $root "scripts\windows\cleanup-m4-point-tracking-proof.jsx";$verify=Join-Path $root "scripts\windows\verify-blank-unsaved-ae.jsx";$opener=Join-Path $root "scripts\windows\open-editflow2-panel.jsx";$cleanupEv=Join-Path $env:TEMP "EditFlow2-m4-point-cleanup.txt";$verifyEv=Join-Path $env:TEMP "EditFlow2-blank-unsaved-proof.txt";$node=$null;$exit=1;$start=Get-Date
function Ae([string]$script,[string]$ev,[string]$prefix){if(Test-Path $ev){Remove-Item $ev -Force};[void](Start-Process -FilePath $AfterFxPath -ArgumentList @("-r",$script)-PassThru);$d=(Get-Date).AddSeconds(4);while((Get-Date)-lt $d){if(Test-Path $ev){$v=(Get-Content $ev -Raw).Trim();if($v.StartsWith($prefix,[StringComparison]::Ordinal)){return $v};throw "AE helper returned '$v'"};Start-Sleep -Milliseconds 50};throw "AE helper timeout"}
function PanelConnected(){try{$c=Get-Content $config -Raw|ConvertFrom-Json;$h=@{"X-EditFlow-Token"=[string]$c.token};$s=Invoke-RestMethod -Method Get -Uri ("http://127.0.0.1:{0}/v1/status"-f[int]$c.port) -Headers $h -TimeoutSec 1;return $s.panelConnected -eq $true}catch{return $false}}
try{New-Item -ItemType Directory -Force -Path $dir|Out-Null;$running=@(Get-Process -Name AfterFX -ErrorAction SilentlyContinue|Where-Object{$_.Responding});if($running.Count-ne1){throw "M4 point proof requires exactly one responsive warm AE process"};$pre=Ae $cleanup $cleanupEv "CLEANED ";$blank=Ae $verify $verifyEv "BLANK_UNSAVED";Write-Host "M4 point preflight: $pre; $blank";Push-Location $root;try{npm run build:test-runtime;if($LASTEXITCODE-ne0){throw "runtime build failed"};$cli=Join-Path $root "scripts\m4-point-tracking-p1-p3.mjs";$args=@($cli,"--config",$config,"--result",$result,"--broker-ready",$ready);$node=Start-Process node -ArgumentList $args -NoNewWindow -PassThru -RedirectStandardOutput $stdout -RedirectStandardError $stderr;$d=(Get-Date).AddSeconds(5);while((Get-Date)-lt$d-and-not(Test-Path $ready)){$node.Refresh();if($node.HasExited){break};Start-Sleep -Milliseconds 50};if(-not(Test-Path $ready)){if(Test-Path $stderr){Get-Content $stderr -Tail 80|Write-Host};throw "M4 point broker not ready"};if(-not(PanelConnected)){[void](Start-Process -FilePath $AfterFxPath -ArgumentList @("-r",$opener)-PassThru)};if(-not $node.WaitForExit($ProofTimeoutSeconds*1000)){Stop-Process $node.Id -Force -ErrorAction SilentlyContinue;throw "M4 point core exceeded $ProofTimeoutSeconds seconds"};$node.WaitForExit()}finally{Pop-Location};if(-not(Test-Path $result)){throw "M4 point proof emitted no result"};$r=Get-Content $result -Raw|ConvertFrom-Json;if($r.ok-ne$true){Get-Content $result -Raw|Write-Host;throw "M4 point machine proof failed"};$post=Ae $cleanup $cleanupEv "CLEANED ";$blankAfter=Ae $verify $verifyEv "BLANK_UNSAVED";$elapsed=[int]((Get-Date)-$start).TotalMilliseconds;Write-Host "M4 point proof PASS coreMs=$($r.elapsedMs) wrapperMs=$elapsed trackerMs=$($r.trackingElapsedMs)";Get-Content $result -Raw|Write-Host;$exit=0}catch{$m=$_.Exception.Message;try{$post=Ae $cleanup $cleanupEv "CLEANED ";Write-Host "Failure cleanup: $post"}catch{};Write-Error $m -ErrorAction Continue;$exit=1}finally{if($node){try{$node.Refresh();if(-not $node.HasExited){Stop-Process $node.Id -Force -ErrorAction SilentlyContinue}}catch{}}};exit $exit
